98	function buildSingleChart(id, label, data, rawLabels, color, unit, range) {
99	  const ctx = document.getElementById(id);
100	  if (!ctx) return;
101	  if (historyCharts[id]) historyCharts[id].destroy();
102	  historyCharts[id] = new Chart(ctx, {
103	    type: 'line',
104	    data: {
105	      labels: rawLabels,
106	      datasets: [{
107	        label: label,
108	        data: data,
109	        borderColor: color,
110	        backgroundColor: `${color}22`,
111	        fill: true,
112	        tension: 0.3,
113	        pointRadius: 0,
114	      }]
115	    },
116	    options: {
117	      responsive: true,
118	      maintainAspectRatio: false,
119	      interaction: { mode: 'index', intersect: false },
120	      plugins: {
121	        legend: { display: false },
122	        tooltip: {
123	          enabled: true,
124	          callbacks: {
125	            title(context) {
126	                const ts = context[0].label;
127	                const d = new Date(ts);
128	                if (Number.isNaN(d.getTime())) return ts;
129	                return d.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
130	            },
131	            label(context) {
132	              return `${label}: ${formatMetric(context.parsed.y, { digits: 1, unit, zeroAsMissing: false })}`;
133	            }
134	          }
135	        }
136	      },
137	      scales: {
138	        x: {
139	            ticks: {
140	                maxRotation: 0,
141	                autoSkip: false,
142	                callback: function(val, index) {
143	                    const ts = rawLabels[index];
144	                    if (!ts) return '';
145	                    const d = new Date(ts);
146	                    if (Number.isNaN(d.getTime())) return '';
147	                    
148	                    const m = d.getMinutes();
149	                    const h = d.getHours();
150	                    const s = d.getSeconds();
151	
152	                    if (range === '1h') {
153	                        // cada 10 min
154	                        if (m % 10 === 0 && s < 30) {
155	                            return d.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
156	                        }
157	                    } else if (range === '12h') {
158	                        // cada hora
159	                        if (m === 0) {
160	                            return d.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
161	                        }
162	                    } else if (range === '24h') {
163	                        // cada 2 horas
164	                        if (h % 2 === 0 && m === 0) {
165	                            return d.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
166	                        }
167	                    }
168	                    return '';
169	                }
170	            }
171	        },
172	        y: { beginAtZero: false }
173	      }
174	    }
175	  });
176	}
