353	    loadRiskArtworks(code),
354	    loadHistory(code),
355	    loadActuators(code),
356	  ]);
357	
358	  document.getElementById('rangeSelect').addEventListener('change', () => loadHistory(code));
359	
360	  const socket = ensureSocket();
361	  socket.on('update', () => loadCenterSnapshot(code));
362	  socket.on('actuators', () => loadActuators(code));
363	  socket.on('alerts', () => {
364	    loadRiskArtworks(code);
