80	function avgReq(artworks) {
81	  if (!artworks.length) return { temperature: 21, humidity: 50, co2: 800, illuminance: 120, noise: 55 };
82	  const sum = artworks.reduce((acc, a) => {
83	    const r = a.conservationRequirements || {};
84	    acc.temperature += (Number(r.temperatureMin || 18) + Number(r.temperatureMax || 22)) / 2;
85	    acc.humidity += (Number(r.humidityMin || 45) + Number(r.humidityMax || 55)) / 2;
86	    acc.co2 += Number(r.co2Max || 900);
87	    acc.illuminance += Number(r.illuminanceMax || 150);
88	    acc.noise += Number(r.noiseMax || 60);
89	    return acc;
90	  }, { temperature: 0, humidity: 0, co2: 0, illuminance: 0, noise: 0 });
91	  const n = artworks.length;
92	  return {
93	    temperature: sum.temperature / n,
94	    humidity: sum.humidity / n,
95	    co2: sum.co2 / n,
96	    illuminance: sum.illuminance / n,
97	    noise: sum.noise / n,
98	  };
99	}
